// Self-updating app: the service worker is regenerated by the server whenever a frontend file
// changes. We poll for it, and reload on the next screen change once the new version is active.
import { toast } from "./util.js";

let reg = null;
let stale = false;

export const isStale = () => stale;

export async function initUpdates() {
  if (!("serviceWorker" in navigator)) return;
  let hadController = !!navigator.serviceWorker.controller;
  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if (hadController) { stale = true; toast("Updated. Applies on the next screen."); }
    hadController = true;
  });
  reg = await navigator.serviceWorker.register("/sw.js", { updateViaCache: "none" });
  const check = () => reg.update().catch(() => {});
  document.addEventListener("visibilitychange", () => { if (!document.hidden) check(); });
  setInterval(check, 15 * 60_000);
}

export async function checkNow() {
  if (!reg) return false;
  await reg.update();
  return true;
}

export function runningVersion() {
  const sw = navigator.serviceWorker?.controller;
  if (!sw) return Promise.resolve(null);
  return new Promise((resolve) => {
    const ch = new MessageChannel();
    ch.port1.onmessage = (e) => resolve(e.data);
    sw.postMessage("version", [ch.port2]);
    setTimeout(() => resolve(null), 1000);
  });
}
